/**
 * Plain-language explanations of official validation rules, keyed by the official rule ID.
 *
 * Every entry is written by hand from the official rule text (see public/rules/rule-catalogue.json,
 * built from the pinned KoSIT configuration). Nothing here is generated by a model. Status
 * "draft" means: written and cross-checked against the rule text by the author, not yet reviewed
 * by a second person. The official message is always shown next to the explanation.
 *
 * `terms` point into terms.ts, which holds the UBL and CII location of each business term.
 */
export type ExplanationText = { meaning: string; cause: string; fix: string };
export type RuleExplanation = {
  terms: string[];
  status: "draft" | "reviewed";
  de: ExplanationText;
  en: ExplanationText;
};

const d = (terms: string[], de: ExplanationText, en: ExplanationText): RuleExplanation => ({
  terms,
  status: "draft",
  de,
  en,
});

/** Shared wording for the "required element missing" family of rules. */
function required(terms: string[], deName: string, enName: string, deWhy: string, enWhy: string): RuleExplanation {
  return d(
    terms,
    {
      meaning: `${deName} fehlt, ist aber Pflicht.`,
      cause: deWhy,
      fix: `${deName} in der Rechnung angeben (Stelle siehe unten) und neu erzeugen.`,
    },
    {
      meaning: `${enName} is missing but mandatory.`,
      cause: enWhy,
      fix: `Add the ${enName.toLowerCase()} to the invoice (location below) and regenerate it.`,
    },
  );
}

